const a="geopolitica-classica-tra-teologia-e-geopolitica-iran",e="geopolitica-classica/tra-teologia-e-geopolitica/iran",i="https://precious-cassata-42205a.netlify.app/geopolitica-classica/tra-teologia-e-geopolitica/iran",o="Caso Iran",u="02",t="Teocrazia rivoluzionaria tra sciismo e potenza regionale: un primo studio sulla repubblica islamica come laboratorio di fusione tra religione e Stato.",l="geopolitica-classica",r="geopolitica-classica/tra-teologia-e-geopolitica",n=[{type:"p",role:"label",runs:[{t:"02"}]},{type:"h",level:2,runs:[{t:"Caso Iran"}],role:"p"},{type:"p",role:"lede",runs:[{t:"Teocrazia rivoluzionaria tra sciismo e potenza regionale: un primo studio sulla repubblica islamica come laboratorio di fusione tra religione e Stato."}]},{type:"p",role:"p",runs:[{t:"«La Repubblica Islamica è il laboratorio perfetto della teologia geopolitica: uno Stato fondato da un ayatollah, guidato da un clero, in attesa di un imam nascosto.»"}]},{type:"p",role:"p",runs:[{t:"MetaHistoria, Caso Iran"}]},{type:"p",role:"p",runs:[{t:"L'Iran è il caso in cui la "},{t:"teologia diventa Costituzione",b:!0},{t:`. La dottrina del velayat-e faqih il "governo del giurisperito" formulata dall'ayatollah Khomeini, stabilisce che in assenza dell'imam nascosto (il Mahdi), la guida della comunità spetta al massimo esperto di diritto islamico. Il clero non consiglia lo Stato: lo `},{t:"governa direttamente",b:!0},{t:"."}]},{type:"p",role:"p",runs:[{t:"Questa è la differenza radicale rispetto a tutti gli altri casi: mentre negli USA la teologia è implicita e in Russia è simfonica, in Iran è "},{t:"costituzionale",b:!0},{t:". Il Consiglio dei Guardiani vaglia le leggi per conformità all'islam. Il Guida Suprema è capo dello Stato e autorità religiosa. Non c'è separazione: c'è identità."}]},{type:"p",role:"p",runs:[{t:"Dario Fabbri leggerebbe l'Iran come una civiltà persiana con un'identità sciita millenaria, plasmata dal "},{t:"martirio e dall'attesa",b:!0},{t:". Lo sciismo duodecimano la convinzione che il dodicesimo imam sia nascosto e ritornerà struttura la percezione del tempo: la storia è attesa, il presente è provvisorio, il futuro è apocalittico."}]},{type:"p",role:"p",runs:[{t:`Il nemico è l'oppressione universale (estekbar): gli Stati Uniti come "Grande Satana", Israele come "Piccolo Satana". Il sacrificio (shahadat, martirio) è il più alto atto di fede e di resistenza: morire per la causa è vivere per sempre. Una teologia del martirio che diventa strategia militare (Hezbollah, milizie sciite, "asse della resistenza").`}]},{type:"h",level:3,runs:[{t:"Analisi per la griglia a quattro livelli"}],role:"p"},{type:"p",role:"p",runs:[{t:"1"}]},{type:"p",role:"p",runs:[{t:"Livello materiale"}]},{type:"p",role:"p",runs:[{t:"Potenza regionale con enormi riserve di gas e petrolio, posizione geografica strategica (Stretto di Hormuz), capacità missilistica. Ma economia"}]},{type:"p",role:"p",runs:[{t:"Potenza regionale con enormi riserve di gas e petrolio, posizione geografica strategica (Stretto di Hormuz), capacità missilistica. Ma economia "},{t:"soffocata dalle sanzioni",b:!0},{t:", tecnologia limitata, demografia giovane ma in transizione. Una potenza che sopravvive alla pressione esterna grazie alla resilienza interna."}]},{type:"p",role:"p",runs:[{t:"La povertà materiale è compensata dalla ricchezza del martirio."}]},{type:"p",role:"p",runs:[{t:"2"}]},{type:"p",role:"p",runs:[{t:"Livello narrativo"}]},{type:"p",role:"p",runs:[{t:'"La Rivoluzione Islamica non è un evento, è un processo."',b:!0},{t:" L'Iran si percepisce come avanguardia della resistenza contro l'oppressione globale. La narrazione di Karbala il martirio di Hussein come archetipo: i pochi giusti contro i molti ingiusti, destinati a vincere perché dalla parte di Dio."}]},{type:"p",role:"p",runs:[{t:"Karbala non è storia: è una mappa geopolitica."}]},{type:"p",role:"p",runs:[{t:"3"}]},{type:"p",role:"p",runs:[{t:"Livello teologico implicito"}]},{type:"p",role:"p",runs:[{t:"Non implicito:"}]},{type:"p",role:"p",runs:[{t:"Non implicito: "},{t:"esplicito e costituzionale",b:!0},{t:". Il velayat-e faqih è teologia applicata alla governance. L'ayatollah Khamenei non è solo capo dello Stato: è l'erede del Profeta. L'islam sciita duodecimano struttura ogni categoria: legge, autorità, giustizia, guerra, pace."}]},{type:"p",role:"p",runs:[{t:"L'unico caso in cui la teologia è la Costituzione."}]},{type:"p",role:"p",runs:[{t:"4"}]},{type:"p",role:"p",runs:[{t:"Livello escatologico"}]},{type:"p",role:"p",runs:[{t:"Escatologia dell'attesa",b:!0},{t:": il Mahdi ritornerà per riempire il mondo di giustizia. Il presente è provvisorio, la storia è un intervallo. Ma l'attesa non è passiva: è lotta per preparare il suo ritorno. La rivoluzione permanente come preparazione escatologica."}]},{type:"p",role:"p",runs:[{t:"L'attesa del Mahdi non paralizza: mobilita."}]},{type:"p",role:"p",runs:[{t:"«L'Iran è l'unico Stato moderno fondato esplicitamente in attesa di un evento escatologico. Non è un'anomalia: è il futuro che il mondo secolarizzato non vuole vedere.»"}]},{type:"p",role:"p",runs:[{t:"«La forza dell'Iran è la sua debolezza: da solo contro il mondo, ma convinto di avere Dio dalla sua parte. Il martirio non è un danno collaterale: è la strategia. Quando il sacrificio è valore supremo, nessuna sconfitta è definitiva.»"}]},{type:"p",role:"p",runs:[{t:"MetaHistoria, Caso Iran — Intuizione"}]}],s=[],p=["C. Schmitt, Teologia politica (1922)","L. Caracciolo, Limes (1993 )","D. Fabbri, Geopolitica umana (2023)","Manifesto TGP-O (2026)"],c={blocks:31,chars:3762,hash:"bb7959111b1957f9176f23cea72985a9722e5b2fef707a26453dcef0625a4c93"},d={id:a,slug:e,sourceUrl:i,title:o,kicker:"02",lede:t,category:l,parentId:r,blocks:n,prevNext:s,references:p,stats:c};export{n as blocks,l as category,d as default,a as id,u as kicker,t as lede,r as parentId,s as prevNext,p as references,e as slug,i as sourceUrl,c as stats,o as title};
